div.wssteampro__pog{text-align:center;border:1px solid rgba(246,201,69,.35);border-radius:16px;transition:transform .2s,box-shadow .2s}div.wssteampro__pog:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(246,201,69,.22)}div.wssteampro__pog>strong,div.wssteampro__pog>span:not(.wssteampro__pi){display:block}
.wssteampro__k--ik .wssteampro__kt{text-align:center;padding:28px 20px}
.wssteampro__pus{color:#8c7427}.wssteampro__plavo{background:#8c7427;margin-top:-72px}.wssteampro__k--temna{background:#8c7427}
@media (max-width:860px){.wssteampro__s{padding:46px 0}.wssteampro__s.wssteampro__traka{padding:30px 0}.wssteampro__plavo{margin-top:-46px}.wssteampro__pog>div{padding:22px 12px}}
@media (max-width:767px){.wssteampro__v{padding:0 16px}}
/* /dizajn.py */
.wssteampro__v>.wssteampro__zak{text-align:center}
.wssteampro__sf--ik{display:flex;gap:14px;align-items:flex-start}.wssteampro__sfik{width:52px;height:52px;flex:0 0 52px;border-radius:14px;object-fit:cover;box-shadow:0 4px 12px rgba(0,0,0,.08)}.wssteampro__sf--ik strong::after{display:none!important}
</style>
<script>
(function(){document.querySelectorAll('.wssteampro__kar').forEach(function(k){
  var w=document.createElement('div');w.className='wssteampro__karw';k.parentNode.insertBefore(w,k);w.appendChild(k);
  ['l','d'].forEach(function(s){var b=document.createElement('button');b.type='button';b.className='wssteampro__pus wssteampro__pus--'+s;b.setAttribute('aria-label',s==='l'?'Prethodno':'Sljedeće');b.innerHTML=s==='l'?'&#8249;':'&#8250;';
    b.addEventListener('click',function(){var x=k.firstElementChild;var d=x?x.getBoundingClientRect().width+22:300;k.scrollBy({left:s==='l'?-d:d,behavior:'smooth'});});w.appendChild(b);});
});})();
</script>
